// Look up a place by name (case-insensitive; exact or prefix match on the
// main/ASCII name, exact match on alternate-name aliases). country
// (ISO-3166 alpha-2) narrows the search. Returns the row with the largest
// population, or null when nothing matches.
function findPlace(city, country) {
    var q = String(city || '').toLowerCase().trim();
    if (q === '') return null;
    var cc = country ? String(country).toUpperCase() : '';
    for (var i = 0; i < GEO_ALIASES.length; i++) {
        var al = GEO_ALIASES[i];
        if (al[0] === q) {
            var r = GEO_CITIES[al[1]];
            if (cc === '' || r[2] === cc) return r;
        }
    }
    var best = null;
    var bestScore = -1;
    for (var j = 0; j < GEO_CITIES.length; j++) {
        var c = GEO_CITIES[j];
        if (cc !== '' && c[2] !== cc) continue;
        var n = c[0].toLowerCase();
        var a = c[1].toLowerCase();
        var sc = (n === q || a === q) ? 2 : (n.indexOf(q) === 0 || a.indexOf(q) === 0) ? 1 : 0;
        if (sc === 0) continue;
        if (sc > bestScore || (sc === bestScore && best && c[6] > best[6])) {
            best = c;
            bestScore = sc;
        }
    }
    return best;
}

// Search candidates for a place name (case-insensitive). Exact name/alias
// matches rank first, then prefix, then substring; ties are broken by
// population. Returns up to `limit` (default 10, max 50) rows as plain
// objects, so a client can pick the correct location when the same name
// exists in different countries (e.g. Rome, IT vs Rome, US).
function searchPlaces(city, country, limit) {
    var q = String(city || '').toLowerCase().trim();
    if (q === '') return [];
    var cc = country ? String(country).toUpperCase() : '';
    var lim = (typeof limit === 'number' && limit > 0) ? Math.min(Math.floor(limit), 50) : 10;
    var best = {};
    var i, j, c;
    for (i = 0; i < GEO_ALIASES.length; i++) {
        var al = GEO_ALIASES[i];
        if (al[0] !== q) continue;
        c = GEO_CITIES[al[1]];
        if (cc !== '' && c[2] !== cc) continue;
        if (!Object.prototype.hasOwnProperty.call(best, al[1]) || best[al[1]] < 4) best[al[1]] = 4;
    }
    for (j = 0; j < GEO_CITIES.length; j++) {
        c = GEO_CITIES[j];
        if (cc !== '' && c[2] !== cc) continue;
        var n = c[0].toLowerCase();
        var a = c[1].toLowerCase();
        var sc = (n === q || a === q) ? 4 : (n.indexOf(q) === 0 || a.indexOf(q) === 0) ? 3 : (n.indexOf(q) !== -1 || a.indexOf(q) !== -1) ? 1 : 0;
        if (sc === 0) continue;
        if (!Object.prototype.hasOwnProperty.call(best, j) || best[j] < sc) best[j] = sc;
    }
    var rows = [];
    for (var k in best) {
        if (Object.prototype.hasOwnProperty.call(best, k)) rows.push([k, best[k]]);
    }
    rows.sort(function (x, y) {
        if (y[1] !== x[1]) return y[1] - x[1];
        var px = GEO_CITIES[x[0]], py = GEO_CITIES[y[0]];
        if (py[6] !== px[6]) return py[6] - px[6];
        if (px[0] < py[0]) return -1;
        if (px[0] > py[0]) return 1;
        return 0;
    });
    var out = [];
    for (var m = 0; m < rows.length && m < lim; m++) {
        var r = GEO_CITIES[rows[m][0]];
        out.push({ name: r[0], country: r[2], latitude: r[3], longitude: r[4],
                   timeZone: r[5], population: r[6] });
    }
    return out;
}
